#!/usr/bin/env bash
# Generate deploy/compose/.env with fresh random LOCAL-ONLY secrets.
# Refuses to overwrite an existing file unless --force is given.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
OUT="$ROOT/deploy/compose/.env"

if [[ -f "$OUT" && "${1:-}" != "--force" ]]; then
  echo "deploy/compose/.env already exists (use --force to regenerate; existing API keys will stop working)."
  exit 0
fi

command -v openssl >/dev/null || { echo "openssl is required" >&2; exit 1; }
rand() { openssl rand -hex 32; }

umask 077
cat >"$OUT" <<ENV
# Generated by scripts/demo/gen-local-env.sh on $(date -u +%Y-%m-%dT%H:%M:%SZ).
# LOCAL-ONLY throwaway secrets. Never reuse these anywhere else.
EVS_DATA_ENCRYPTION_KEY=$(rand)
EVS_API_KEY_PEPPER=$(rand)
EVS_PLAYBACK_SIGNING_KEYS=k1=$(rand)
EVS_PLAYBACK_ACTIVE_KID=k1
ENV
echo "wrote deploy/compose/.env (mode 600)"
